CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE "Reservation" ADD CONSTRAINT reservation_dates CHECK ("endAt">"startAt");
ALTER TABLE "Reservation" ADD CONSTRAINT reservation_state CHECK (state IN ('HOLD','CONFIRMED','ACTIVE','ENDED','EXPIRED','CANCELLED','BLOCKED'));
ALTER TABLE "Reservation" ADD CONSTRAINT hold_expiry CHECK (state<>'HOLD' OR "expiresAt" IS NOT NULL);
ALTER TABLE "Reservation" ADD CONSTRAINT no_overlapping_bed EXCLUDE USING gist ("bedId" WITH =, tsrange("startAt","endAt",'[)') WITH &&) WHERE (state IN ('HOLD','CONFIRMED','ACTIVE','BLOCKED'));
ALTER TABLE "Reservation" ADD CONSTRAINT no_overlapping_resident EXCLUDE USING gist ("userId" WITH =, tsrange("startAt","endAt",'[)') WITH &&) WHERE (state IN ('HOLD','CONFIRMED','ACTIVE'));
ALTER TABLE "Charge" ADD CONSTRAINT charge_positive CHECK ("amountMinor">0);
ALTER TABLE "Payment" ADD CONSTRAINT payment_positive CHECK ("amountMinor">0);
ALTER TABLE "Allocation" ADD CONSTRAINT allocation_positive CHECK ("amountMinor">0);
ALTER TABLE "Credit" ADD CONSTRAINT credit_positive CHECK ("amountMinor">0);
ALTER TABLE "Refund" ADD CONSTRAINT refund_positive CHECK ("amountMinor">0);
ALTER TABLE "AllocationReversal" ADD CONSTRAINT reversal_positive CHECK ("amountMinor">0);
ALTER TABLE "Room" ADD CONSTRAINT rent_nonnegative CHECK ("monthlyMinor">=0);
ALTER TABLE "Property" ADD CONSTRAINT property_policy CHECK ("holdMinutes" BETWEEN 5 AND 1440 AND "depositMinor">=0 AND currency ~ '^[A-Z]{3}$');
CREATE FUNCTION reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Immutable record: append a correction'; END; $$;
CREATE TRIGGER immutable_audit BEFORE UPDATE OR DELETE ON "AuditEvent" FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_receipt BEFORE UPDATE OR DELETE ON "Receipt" FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_charge BEFORE UPDATE OR DELETE ON "Charge" FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_allocation BEFORE UPDATE OR DELETE ON "Allocation" FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_refund BEFORE UPDATE OR DELETE ON "Refund" FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_credit BEFORE UPDATE OR DELETE ON "Credit" FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_reversal BEFORE UPDATE OR DELETE ON "AllocationReversal" FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE TRIGGER immutable_lease_event BEFORE UPDATE OR DELETE ON "LeaseEvent" FOR EACH ROW EXECUTE FUNCTION reject_mutation();
CREATE FUNCTION protect_executed_lease() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD."executedAt" IS NOT NULL THEN RAISE EXCEPTION 'Executed lease is immutable'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER immutable_executed_lease BEFORE UPDATE OR DELETE ON "Lease" FOR EACH ROW EXECUTE FUNCTION protect_executed_lease();
CREATE FUNCTION protect_posted_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR (OLD."settledAt" IS NOT NULL AND (NEW."amountMinor"<>OLD."amountMinor" OR NEW.currency<>OLD.currency OR NEW."userId"<>OLD."userId" OR NEW.reference<>OLD.reference OR NEW."propertyId"<>OLD."propertyId")) THEN RAISE EXCEPTION 'Posted payment evidence is immutable'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER protect_posted_payment BEFORE UPDATE OR DELETE ON "Payment" FOR EACH ROW EXECUTE FUNCTION protect_posted_payment();
